def get_strategy_list(user_id, business_type=None):
    strategy_list = []
    strategy_dir_path = os.path.join(STRATEGY_DIR_PATH, user_id)
    user_copy_datfile(STRATEGY_DEMO_DIR_PATH, strategy_dir_path)
    if os.path.exists(strategy_dir_path):
        dat_file_list = get_dir_file_name(strategy_dir_path, '.dat')
        tmp_dict = {}
        gd_tmp_dict = {}
        gd_order_list = {}
        order_list = {}
        for _file in dat_file_list:
            dat_file_path = os.path.join(strategy_dir_path, _file)
            if 'gd_' in dat_file_path:
                gd_tmp_dict[dat_file_path] = _file.replace('.dat', '').split('-')[-1]
                continue
            tmp_dict[dat_file_path] = os.path.getmtime(dat_file_path)
            continue
        else:
            if gd_tmp_dict:
                gd_order_list = sorted(gd_tmp_dict.items(), key=lambda item: item[1], reverse=False)
            if tmp_dict:
                order_list = sorted(tmp_dict.items(), key=lambda e: e[1], reverse=True)
        for data_list in (gd_order_list, order_list):
            for _item in data_list:
                strategy = get_strategy(user_id, os.path.split(_item[0])[1].split('.')[0])
                if strategy is not None:
                    strategy['strategy_type'] = strategy.get('strategy_type', COMMON_STRATEGY_TYPE)
                    if 'CUSTOM' in strategy['id']:
                        continue
                    elif strategy['strategy_type'] == '1':
                        continue
                    else:
                        try:
                            strategy['update_time'] = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(_item[1]))
                        except:
                            strategy['update_time'] = '2000-01-01 00:00:00'
                        if not strategy.get('business_mode'):
                            strategy['business_mode'] = BUSINESS_MODE_2
                        if not business_type is not None or business_type == strategy.get('business_type', 'stock'):
                            strategy['content'] = content_trailing_handle(strategy['content'])
                            strategy_list.append(strategy)
    return strategy_list
def user_copy_datfile(src_dir, des_dir):
    if os.path.exists(src_dir):
        dat_file_list = os.listdir(src_dir)
        demo_dat_list = []
        strategy_status = {}
        for _file in dat_file_list:
            if _file.endswith('.dat'):
                demo_dat_list.append(_file)
            continue
        else:
            if os.path.exists(des_dir):
                status_path = os.path.join(des_dir, 'demo_strategy_status.csv')
                if os.path.exists(status_path):
                    df_status = pd.read_csv(status_path, index_col=0)
                    for file_dat in demo_dat_list:
                        if file_dat not in df_status.index:
                            demo_dat_path = os.path.join(src_dir, file_dat)
                            shutil.copy(demo_dat_path, des_dir)
                            strategy_status[file_dat] = '1'
                        continue
                    else:
                        if strategy_status:
                            append_df_status = pd.DataFrame({'status': strategy_status})
                            df_status = df_status.append(append_df_status)
                            df_status.to_csv(status_path)
                else:
                    for file_dat in demo_dat_list:
                        demo_dat_path = os.path.join(src_dir, file_dat)
                        user_dat_path = os.path.join(des_dir, file_dat)
                        if not os.path.exists(user_dat_path):
                            shutil.copy(demo_dat_path, des_dir)
                        strategy_status[file_dat] = '1'
                    else:
                        if strategy_status:
                            df_status = pd.DataFrame({'status': strategy_status})
                            df_status.to_csv(status_path)
            else:
                os.mkdir(des_dir)
                user_copy_datfile(src_dir, des_dir)
def get_strategy(user_id, strategy_id):
    strategy_file_path = os.path.join(STRATEGY_DIR_PATH, user_id, strategy_id + '.dat')
    strategy_profile_file_path = os.path.join(STRATEGY_DIR_PATH, user_id, STRATEGY_PROFILE)
    if os.path.exists(strategy_file_path):
        try:
            strategy = json.JSONDecoder().decode(json.load(open(strategy_file_path, 'r')))
        except BaseException:
            system_log.error(f'解析用户{user_id!s}策略{strategy_id!s}失败，错误原因：{get_traceback_message()!s}')
            return None
        content = strategy['content']
        strategy['business_type'] = strategy.get('business_type', 'stock')
        strategy['benchmark'] = strategy.get('benchmark', '000300.SS')
        strategy['price_impact'] = strategy.get('price_impact', 0.1)
        strategy['volume_limit'] = strategy.get('volume_limit', 25)
        strategy['user_variables'] = strategy.get('user_variables', None)
        strategy['user_variable_desc'] = strategy.get('user_variable_desc', None)
        strategy['code_extend'] = strategy.get('code_extend', '')
        is_encryption = strategy.get('is_encryption', '0')
        if is_encryption in (ENCRYPTION_MODE_1, ENCRYPTION_MODE_2):
            error_no, error_info, session_key, session_iv = PyRead_AES_Binary(strategy_profile_file_path, strategy_id)
            if error_no == 0:
                content = aes_decrypt(content, aes_key=session_key, aes_iv=session_iv)
                strategy['content'] = content
            else:
                system_log.error('error_encryption: %s' % error_info)
            if IS_ENCRYPTION == ENCRYPTION_MODE_0:
                strategy['is_encryption'] = IS_ENCRYPTION
                json.dump(json.JSONEncoder().encode(strategy), open(strategy_file_path, 'w'))
        elif IS_ENCRYPTION in (ENCRYPTION_MODE_1, ENCRYPTION_MODE_2) and len(strategy_id) == 36:
            error_no, error_info, session_key, session_iv = PyRead_AES_Binary(strategy_profile_file_path, strategy_id)
            if error_no == CRYPTO_ERROR_CODE['CRYPTO_IDNOTEXIST_ERROR'] or error_no == CRYPTO_ERROR_CODE['CRYPTO_NOTEXIST_ERROR']:
                session_key = str(uuid.uuid1()).replace('-', '')
                session_iv = str(uuid.uuid1())[0:19].replace('-', '')
                error_no, error_info = PyWrite_AES_Binary(strategy_profile_file_path, strategy_id, session_key, session_iv)
            if error_no == 0:
                strategy['is_encryption'] = IS_ENCRYPTION
                content = aes_encrypt(content, aes_key=session_key, aes_iv=session_iv, return_str=True)
                strategy_copy = strategy.copy()
                strategy_copy['content'] = content
                json.dump(json.JSONEncoder().encode(strategy_copy), open(strategy_file_path, 'w'))
            else:
                app_log.info(f'error_no: {error_no!s} error_encryption: {error_info!s}，加密未加密策略失败，策略ID{strategy_id!s}')
        strategy['content'] = content_trailing_handle(strategy['content'])
        return strategy
    else:
        system_log.error(f'用户{user_id!s}策略{strategy_id!s}文件不存在，无法执行查询操作')
def get_upload_strategy(user_id, strategy_id):
    strategy_id_path = os.path.join(STRATEGY_DIR_PATH, user_id, strategy_id)
    strategy_profile_path = os.path.join(STRATEGY_DIR_PATH, user_id, STRATEGY_PROFILE)
    if os.path.exists(strategy_id_path):
        strategy_id_file_path = os.path.join(strategy_id_path, USER_CODE_DAT)
        strategy = json.JSONDecoder().decode(json.load(open(strategy_id_file_path, 'r', encoding='utf-8')))
        strategy['business_type'] = strategy.get('business_type', 'stock')
        strategy['benchmark'] = strategy.get('benchmark', '000300.SS')
        strategy['price_impact'] = strategy.get('price_impact', 0.1)
        strategy['volume_limit'] = strategy.get('volume_limit', 25)
        strategy['user_variables'] = strategy.get('user_variables', None)
        strategy['user_variable_desc'] = strategy.get('user_variable_desc', None)
        strategy['code_extend'] = strategy.get('code_extend', '')
        error_no, error_info, session_key, session_iv = PyRead_AES_Binary(strategy_profile_path, strategy_id)
        if error_no == 0:
            strategy['content'] = aes_decrypt(strategy['content'], session_key.decode('utf-8'), session_iv.decode('utf-8'))
            return strategy
        else:
            system_log.error(f'用户{user_id!s}策略{strategy_id!s}解密失败，错误原因：{error_info!s}')
    else:
        system_log.error(f'用户{user_id!s}策略文件{strategy_id_path!s}不存在，无法获取对应策略')
