def check_strategy_name(user_id, strategy_name):
    base_dir = os.path.join(STRATEGY_DIR_PATH, user_id)
    if not os.path.isdir(base_dir):
        return True
    else:
        for filename in os.listdir(base_dir):
            if not filename.endswith('.dat'):
                continue
            strategy_data = get_strategy(user_id, filename.split('.')[0])
            if strategy_data.get('name') == strategy_name:
                return False
        else:
            return True
