def strategy_name_modify(user_id, strategy_id, strategy_name):
    strategy_file_path = os.path.join(STRATEGY_DIR_PATH, user_id, strategy_id + '.dat')
    if os.path.exists(strategy_file_path):
        try:
            strategy = json.JSONDecoder().decode(json.load(open(strategy_file_path, 'r')))
        except BaseException:
            msg = f'解析用户{user_id!s}策略{strategy_id!s}失败，错误原因：{get_traceback_message()!s}'
            system_log.error(msg)
            return {'error_no': -1, 'error_info': msg}
        if strategy_name is not None and strategy_name.strip() != '':
            strategy['name'] = strategy_name
        else:
            msg = '入参策略名称异常：%s' % strategy_name
            system_log.error(msg)
            return {'error_no': -1, 'error_info': msg}
        json.dump(json.JSONEncoder().encode(strategy), open(strategy_file_path, 'w'))
        strategy = get_strategy(user_id, strategy_id)
        if strategy is None:
            msg = f'用户{user_id!s}策略{strategy_id!s}保存失败，删除策略文件'
            os.system('rm -rf %s' % strategy_file_path)
            system_log.warning(msg)
            return {'error_no': -1, 'error_info': msg}
        else:
            return {'error_no': 0, 'error_info': ''}
    else:
        msg = f'用户{user_id!s}策略{strategy_id!s}文件不存在，无法执行保存操作'
        system_log.error(msg)
        return {'error_no': -1, 'error_info': msg}
def handle_strategy_creation(strategy_name):
    response = get_strategy_code_info(strategy_name)
    if response.get('error_no', -1) != 0:
        system_log.error('获取策略代码信息失败，错误原因：{}'.format(response.get('error_info')))
        return response
    else:
        file_content = response.get('file_content')
        parameter_content = response.get('parameter_content')
        response = save_clsc_strategy_content(strategy_name, file_content)
        if response.get('error_no', -1) != 0:
            return response
        else:
            response = save_clsc_strategy_params(strategy_name, parameter_content)
            return response
